//*****************************************************************************
//
// buzzer.c - Tone on the buzzer (PG1), generated by the Timer0 interrupt
//
// The buzzer needs a square wave. Every time Timer0 runs out, the ISR
// switches PG1 (high -> low -> high ...). One period of the tone needs two
// switches, so the timer has to run out with twice the tone frequency:
//
//   load value = sysClock / (2 * freq)
//   example 440 Hz: 120 000 000 / 880 = 136 363
//
//*****************************************************************************

#include <stdint.h>
#include <stdbool.h>
#include "inc/hw_memmap.h"
#include "inc/hw_ints.h"
#include "driverlib/gpio.h"
#include "driverlib/sysctl.h"
#include "driverlib/timer.h"
#include "driverlib/interrupt.h"
#include "buzzer.h"

static uint32_t clockHz;   // system clock, needed to calculate the load value

void buzzer_init(uint32_t sysClock)
{
    clockHz = sysClock;

    // switch on the clock of port G and Timer0 and wait until they are ready
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOG);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_TIMER0);
    while (!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOG) ||
           !SysCtlPeripheralReady(SYSCTL_PERIPH_TIMER0))
    {
    }

    // PG1 = buzzer, output, low
    GPIOPinTypeGPIOOutput(GPIO_PORTG_BASE, GPIO_PIN_1);
    GPIOPinWrite(GPIO_PORTG_BASE, GPIO_PIN_1, 0);

    // Timer0: periodic (starts again automatically), interrupt when it runs out
    TimerConfigure(TIMER0_BASE, TIMER_CFG_PERIODIC);
    TimerIntEnable(TIMER0_BASE, TIMER_TIMA_TIMEOUT);
    IntEnable(INT_TIMER0A);
    // the timer is started later by buzzer_start()
}

void buzzer_start(uint32_t freq)
{
    TimerDisable(TIMER0_BASE, TIMER_A);
    TimerLoadSet(TIMER0_BASE, TIMER_A, clockHz / (2 * freq));
    TimerEnable(TIMER0_BASE, TIMER_A);
}

void buzzer_stop(void)
{
    TimerDisable(TIMER0_BASE, TIMER_A);
    GPIOPinWrite(GPIO_PORTG_BASE, GPIO_PIN_1, 0);   // pin low = silent
}

// Interrupt service routine of Timer0, called with twice the tone frequency
void Timer0AIntHandler(void)
{
    // clear the interrupt flag, otherwise the ISR is called again immediately
    TimerIntClear(TIMER0_BASE, TIMER_TIMA_TIMEOUT);

    // invert PG1: read the pin and write the opposite value
    GPIOPinWrite(GPIO_PORTG_BASE, GPIO_PIN_1,
                 GPIOPinRead(GPIO_PORTG_BASE, GPIO_PIN_1) ^ GPIO_PIN_1);
}
